const translateStatus = (value: string, lang: Lang) => lang === 'en' ? ({'نشط':'Active','قيد المراجعة':'Pending','معتمد':'Approved','مرفوض':'Rejected','منتهي':'Expired','مسدد':'Paid','حاضر':'Present','متأخر':'Late','غائب':'Absent','عن بُعد':'Remote','جاهز':'Ready','قيد المعالجة':'Processing'}[value] || value) : value;
const number = (value: number, lang: Lang) => new Intl.NumberFormat(lang === 'ar' ? 'ar-SA' : 'en-US').format(value);
const expiryDays = (date?: string) => date ? Math.ceil((new Date(`${date}T00:00:00`).getTime() - new Date(new Date().toDateString()).getTime()) / 86400000) : null;
const expiryBand = (days: number) => days <= 7 ? 7 : days <= 15 ? 15 : days <= 30 ? 30 : 45;
const initialData = Object.fromEntries(modules.map(m => [m.key, m.sample]));

type DashboardProps={apiBaseUrl?:string;token?:string;user?:{id:string;email:string;fullName:string;role:string};onLogout?:()=>void;onChangeDeployment?:()=>void};
type TeamUser={id:string;email:string;fullName:string;role:string;isActive:boolean};
type Overview={employeeCount:number;presentCount:number;pendingLeaves:number;payrollTotal:number;absenceDays:number;totalLeaveDays:number;advancesTotal:number;expiredContracts:number;averageSalary:number;expiryBands:Record<number,number>;dueDocuments:Array<{id:string;name:string;documentType:string;authority?:string|null;employeeName?:string|null;expiresOn:string;module:'companyDocs'|'employeeDocs';daysRemaining:number}>;expiredDocuments:Array<{id:string;name:string;documentType:string;authority?:string|null;employeeName?:string|null;expiresOn:string;module:'companyDocs'|'employeeDocs';daysRemaining:number}>};
export function Dashboard({apiBaseUrl,token,user,onLogout,onChangeDeployment}:DashboardProps={}) {
  const remoteMode=Boolean(apiBaseUrl&&token);
  const emptyData=Object.fromEntries(modules.map(m=>[m.key,[]])) as Record<string,Row[]>;
  const [lang, setLang] = useState<Lang>(() => (localStorage.getItem('rakeza-language') as Lang) || 'ar');
  const [data, setData] = useState<Record<string, Row[]>>(() => { if(remoteMode)return emptyData;try { const stored=JSON.parse(localStorage.getItem('rakeza-data')||'null'); return stored?{...initialData,...stored}:initialData; } catch { return initialData; } });
  const [active, setActive] = useState('dashboard');
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [currentPage,setCurrentPage]=useState(1);
  const [moduleTotals,setModuleTotals]=useState<Record<string,number>>({});
  const [overview,setOverview]=useState<Overview|null>(null);
  const [expandedEmployees, setExpandedEmployees] = useState<Record<string,boolean>>({});
  const [teamUsers,setTeamUsers]=useState<TeamUser[]>([]);
  const [editing, setEditing] = useState<Row | null>(null);
  const [form, setForm] = useState<Record<string,string>>({});
  const [pendingAttachment, setPendingAttachment] = useState<File|null>(null);
  const [,setClockPulse] = useState(0);
  const [mobileNav, setMobileNav] = useState(false);
  const [toast, setToast] = useState('');
  const t = (key: string) => labels[key]?.[lang] ?? key;
  const isAr = lang === 'ar';
  const apiRequest=async(path:string,options:RequestInit={})=>{if(!apiBaseUrl||!token)throw new Error('API connection is not configured');const headers=new Headers(options.headers);headers.set('Authorization',`Bearer ${token}`);if(options.body&&typeof options.body==='string')headers.set('Content-Type','application/json');const response=await fetch(`${apiBaseUrl}${path}`,{...options,headers});if(response.status===204)return null;const result=await response.json().catch(()=>null);if(!response.ok)throw new Error(result?.message||`Request failed (${response.status})`);return result;};
  useEffect(() => { if(!remoteMode)localStorage.setItem('rakeza-data', JSON.stringify(data)); }, [data,remoteMode]);
  useEffect(() => { if(!remoteMode)return;let active=true;apiRequest('/api/v1/overview').then(result=>{if(active)setOverview(result);}).catch(error=>{if(active)setToast(error instanceof Error?error.message:'Could not load summary');});return()=>{active=false;};}, [apiBaseUrl,token,remoteMode,data]);
  useEffect(() => { if(!remoteMode)return;const module=modules.find(item=>item.key===active);if(!module)return;let activeRequest=true;const timer=setTimeout(()=>{const params=new URLSearchParams({page:String(currentPage),pageSize:'50',q:search,status:statusFilter});apiRequest(`/api/v1/modules/${module.key}?${params}`).then(result=>{if(activeRequest){setData(prev=>({...prev,[module.key]:result.items as Row[]}));setModuleTotals(prev=>({...prev,[module.key]:result.total}));}}).catch(error=>{if(activeRequest)setToast(error instanceof Error?error.message:'Could not load records');});},180);return()=>{activeRequest=false;clearTimeout(timer);};},[apiBaseUrl,token,remoteMode,active,currentPage,search,statusFilter]);
  useEffect(()=>{if(!remoteMode||user?.role!=='admin')return;let active=true;apiRequest('/api/admin/users').then(result=>{if(active)setTeamUsers(result.items);}).catch(()=>{});return()=>{active=false;};},[apiBaseUrl,token,remoteMode,user?.role]);
  useEffect(() => { localStorage.setItem('rakeza-language', lang); document.documentElement.lang = lang; document.documentElement.dir = isAr ? 'rtl' : 'ltr'; }, [lang, isAr]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(''), 2600); return () => clearTimeout(timer); }, [toast]);
  useEffect(() => { const timer=setInterval(()=>setClockPulse(Date.now()),60000); return ()=>clearInterval(timer); }, []);

  const current = modules.find(m => m.key === active);
  const rows = current ? (data[current.key] || []) : [];
  const totalRows=current?(remoteMode?(moduleTotals[current.key]||0):rows.length):0;
  const pageCount=Math.max(1,Math.ceil(totalRows/50));
  const filtered = useMemo(() => remoteMode?rows:rows.filter(row => { const matchesSearch=Object.values(row).some(v=>v.toLowerCase().includes(search.toLowerCase())); const days=expiryDays(row.expiresOn); const docs=['companyDocs','employeeDocs'].includes(current?.key||''); const matchesStatus=!statusFilter||(docs?(statusFilter==='expired'?(days!==null&&days<0):statusFilter==='expiring'?(days!==null&&days>=0&&days<=45):(days!==null&&days>45)):row.status===statusFilter); return matchesSearch&&matchesStatus; }), [rows, search, statusFilter, current?.key,remoteMode]);
  const tableFields = current?.key==='employeeDocs' ? current.fields.filter(f=>!['employeeName','employeeNumber'].includes(f.key)) : current?.fields || [];
  const employeeGroups = useMemo(()=>{const grouped=new Map<string,Row[]>();for(const row of filtered){const key=row.employeeNumber||row.employeeName||row.id;grouped.set(key,[...(grouped.get(key)||[]),row]);}return Array.from(grouped,([key,items])=>({key,rows:items}));},[filtered]);
  const employeeCount = remoteMode?(overview?.employeeCount||0):data.employees?.length || 0;
  const presentCount = remoteMode?(overview?.presentCount||0):(data.attendance || []).filter(r => r.status === 'حاضر' || r.status === 'عن بُعد').length;
  const pendingLeaves = remoteMode?(overview?.pendingLeaves||0):(data.leaves || []).filter(r => r.status === 'قيد المراجعة').length;
  const payrollTotal = remoteMode?(overview?.payrollTotal||0):(data.payroll || []).reduce((sum,r) => sum + (Number(r.salary)||0), 0);
  const absenceDays = remoteMode?(overview?.absenceDays||0):(data.absence || []).reduce((sum,r) => sum + (Number(r.days)||0), 0);
  const totalLeaveDays = remoteMode?(overview?.totalLeaveDays||0):(data.leaves || []).reduce((sum,r) => sum + (Number(r.days)||0), 0);
  const advancesTotal = remoteMode?(overview?.advancesTotal||0):(data.advances || []).reduce((sum,r) => sum + (Number(r.amount)||0), 0);
  const expiredContracts = remoteMode?(overview?.expiredContracts||0):(data.contracts || []).filter(r => r.status === 'منتهي').length;
  const averageSalary = remoteMode?(overview?.averageSalary||0):data.payroll?.length ? Math.round(payrollTotal / data.payroll.length) : 0;
  const documents:GroupedDocument[] = [...(data.companyDocs || []).map(row=>({row, documentGroup:'companyDocs' as const})), ...(data.employeeDocs || []).map(row=>({row, documentGroup:'employeeDocs' as const}))];
  const dueDocuments:DueDocument[] = documents.map(item=>({ ...item, daysRemaining:expiryDays(item.row.expiresOn) })).filter((item):item is DueDocument=>item.daysRemaining !== null && item.daysRemaining >= 0 && item.daysRemaining <= 45).sort((a,b)=>a.daysRemaining-b.daysRemaining);
  const expiredDocuments:GroupedDocument[] = documents.filter(item=>{const days=expiryDays(item.row.expiresOn);return days!==null&&days<0;});
  if(remoteMode&&overview){dueDocuments.splice(0,dueDocuments.length,...overview.dueDocuments.map(doc=>({row:{id:doc.id,name:doc.name,documentType:doc.documentType,authority:doc.authority||'',employeeName:doc.employeeName||'',expiresOn:doc.expiresOn},documentGroup:doc.module,daysRemaining:doc.daysRemaining})));expiredDocuments.splice(0,expiredDocuments.length,...overview.expiredDocuments.map(doc=>({row:{id:doc.id,name:doc.name,documentType:doc.documentType,authority:doc.authority||'',employeeName:doc.employeeName||'',expiresOn:doc.expiresOn},documentGroup:doc.module})));}

  const startCreate = () => { setEditing(null); setPendingAttachment(null); setForm({status: current?.fields.find(f=>f.key==='status')?.options?.[0] || ''}); };
  const startEdit = (row: Row) => { setEditing(row); setPendingAttachment(null); setForm({...row}); };
  const saveRecord = async () => {
    if (!current) return;
    const required = current.fields.filter(f => ['name','number','employeeName'].includes(f.key));
    if (required.some(f => !form[f.key]?.trim()) || (['companyDocs','employeeDocs'].includes(current.key) && (!form.documentNo?.trim() || !form.expiresOn))) { setToast(isAr ? 'يرجى إكمال الحقول المطلوبة' : 'Please complete the required fields'); return; }
    if (['companyDocs','employeeDocs'].includes(current.key) && form.issuedOn && (form.expiresOn||'') < form.issuedOn) { setToast(isAr ? 'تاريخ الانتهاء يجب أن يأتي بعد تاريخ الإصدار' : 'Expiry date must be after issue date'); return; }
    let saved:Row = {...form, id: editing?.id || crypto.randomUUID()};let persisted=false;
    try{
      if(remoteMode){
        saved=await apiRequest(editing?`/api/v1/modules/${current.key}/${saved.id}`:`/api/v1/modules/${current.key}`,{method:editing?'PUT':'POST',body:JSON.stringify(saved)});persisted=true;
        if(pendingAttachment){const mime=pendingAttachment.type||({pdf:'application/pdf',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',webp:'image/webp'}[pendingAttachment.name.split('.').pop()?.toLowerCase()||'']);if(!mime)throw new Error(isAr?'نوع الملف غير مدعوم. استخدم PDF أو PNG أو JPG أو WEBP.':'Unsupported file type. Use PDF, PNG, JPG, or WEBP.');const uploaded=await apiRequest(`/api/v1/modules/${current.key}/${saved.id}/attachment`,{method:'PUT',headers:{'Content-Type':mime,'X-File-Name':encodeURIComponent(pendingAttachment.name)},body:pendingAttachment});saved={...saved,attachmentName:uploaded.name,attachmentId:uploaded.id};}
      }else if(pendingAttachment){await storeDocumentFile(saved.id,pendingAttachment);saved.attachmentName=pendingAttachment.name;}
    }catch(error){if(persisted)setEditing(saved);setToast(error instanceof Error?error.message:(isAr?'تعذر حفظ السجل':'Could not save record'));return;}
    setData(prev => ({...prev, [current.key]: (prev[current.key]||[]).some(r=>r.id===saved.id)?(prev[current.key]||[]).map(r => r.id === saved.id ? saved : r):[saved, ...(prev[current.key]||[])]}));
    setForm({}); setEditing(null); setPendingAttachment(null); setToast(isAr ? 'تم حفظ السجل بنجاح' : 'Record saved successfully');
  };
  const removeRecord = async (row: Row) => { if (!current || !window.confirm(t('deleteConfirm'))) return;try{if(remoteMode)await apiRequest(`/api/v1/modules/${current.key}/${row.id}`,{method:'DELETE'});else if(['companyDocs','employeeDocs'].includes(current.key))await removeDocumentFile(row.id);}catch(error){setToast(error instanceof Error?error.message:'Could not delete record');return;}setData(prev => ({...prev,[current.key]:(prev[current.key]||[]).filter(r=>r.id!==row.id)}));setToast(isAr ? 'تم حذف السجل' : 'Record deleted'); };
  const downloadDocument = async (row:Row) => { try { let file:Blob|undefined;if(remoteMode){if(!row.attachmentId)throw new Error('missing');const response=await fetch(`${apiBaseUrl}/api/v1/attachments/${row.attachmentId}`,{headers:{Authorization:`Bearer ${token}`}});if(!response.ok)throw new Error('missing');file=await response.blob();}else file=await readDocumentFile(row.id);if(!file)throw new Error('missing');const url=URL.createObjectURL(file);const link=document.createElement('a');link.href=url;link.download=row.attachmentName||'document';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch{setToast(isAr?'تعذر العثور على الملف':'Attachment was not found');} };
  const createTeamUser=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();const formElement=event.currentTarget;const formData=new FormData(formElement);try{const created=await apiRequest('/api/admin/users',{method:'POST',body:JSON.stringify({fullName:String(formData.get('fullName')),email:String(formData.get('email')),password:String(formData.get('password')),role:String(formData.get('role'))})});setTeamUsers(items=>[...items,created]);formElement.reset();setToast(isAr?'تم إنشاء حساب المستخدم':'User account created');}catch(error){setToast(error instanceof Error?error.message:'Could not create user');}};
  const toggleTeamUser=async(item:TeamUser)=>{try{const next=!item.isActive;await apiRequest(`/api/admin/users/${item.id}`,{method:'PATCH',body:JSON.stringify({isActive:next})});setTeamUsers(items=>items.map(user=>user.id===item.id?{...user,isActive:next}:user));}catch(error){setToast(error instanceof Error?error.message:'Could not update user');}};
  const exportExcel = async () => {
    if (!current) return;
    const XLSX=await import('xlsx');
    const records = filtered.map(row=>Object.fromEntries(current.fields.map(f=>[isAr?f.label:fieldEn(f.label),f.type==='computed'?expiryDescription(row.expiresOn,lang):f.type==='file'?row.attachmentName||'':row[f.key]||''])));
    const sheet = XLSX.utils.json_to_sheet(records);
    sheet['!cols'] = current.fields.map(f=>({wch:Math.max(14,(isAr?f.label:fieldEn(f.label)).length+4)}));
    const workbook = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(workbook,sheet,(isAr?current.ar:current.en).slice(0,31));
    XLSX.writeFile(workbook,`rakeza-${current.key}.xlsx`);
  };
  const exportPdf = () => { const oldTitle=document.title; document.title=`${current?(isAr?current.ar:current.en):t('brand')} - Rakeza HR`; window.onafterprint=()=>{document.title=oldTitle;window.onafterprint=null;}; if(current?.key==='employeeDocs'){setExpandedEmployees(Object.fromEntries(employeeGroups.map(group=>[group.key,true])));setTimeout(()=>window.print(),80);}else window.print(); };
  const createBackup=async()=>{try{const result=await apiRequest('/api/admin/backup',{method:'POST'});setToast(isAr?`حُفظت النسخة محلياً: ${result.location}`:`Local backup created: ${result.location}`);}catch(error){setToast(error instanceof Error?error.message:'Could not create backup');}};
  const groups = [
    {title:'overview',keys:['dashboard']}, {title:'people',keys:['employees','attendance','absence','leaves']},
    {title:'finance',keys:['payroll','advances']}, {title:'documents',keys:['contracts','companyDocs','employeeDocs','files','reports']},
  ];
  const go = (key:string) => { setActive(key); setSearch(''); setStatusFilter(''); setCurrentPage(1); setMobileNav(false); };
  const renderDataRow = (row:Row) => <tr key={row.id}>{tableFields.map(f=><td key={f.key}>{f.type==='computed'?<ExpiryBadge date={row.expiresOn} lang={lang} t={t}/>:f.type==='file'?row.attachmentName?<button className="attachment-link" onClick={()=>downloadDocument(row)}><Paperclip size={14}/>{row.attachmentName}</button>:<span className="muted-dash">—</span>:f.key==='status'?<span className={`status-pill ${statusTone(row.status)}`}><i/>{translateStatus(row.status,lang)}</span>:row[f.key]||<span className="muted-dash">—</span>}</td>)}<td><div className="row-actions"><button className="icon-btn" onClick={()=>startEdit(row)} title={t('edit')}><Pencil size={16}/></button><button className="icon-btn danger-hover" onClick={()=>removeRecord(row)} title={t('delete')}><Trash2 size={16}/></button></div></td></tr>;

  return <div className={`app-shell ${isAr?'is-rtl':'is-ltr'}`} dir={isAr?'rtl':'ltr'}>
    <aside className={`sidebar ${mobileNav?'sidebar--open':''}`}>
      <div className="brand"><div className="brand-mark"><img src="/rakeza-mark.jpg" alt="Rakeza HR"/></div><div><strong>{t('brand')}</strong><span>Human Capital Platform</span></div><button className="icon-btn sidebar-close" onClick={()=>setMobileNav(false)} aria-label="Close"><X size={19}/></button></div>
      <div className="workspace"><div className="workspace-avatar">RK</div><div className="workspace-copy"><b>{isAr?'شركة ركيزة':'Rakeza Company'}</b><small>{isAr?'مساحة العمل':'Workspace'}</small></div><ChevronDown size={16}/></div>
      <nav className="side-nav" aria-label={t('nav')}>
        {groups.map(group=><div className="nav-group" key={group.title}><div className="nav-label">{t(group.title)}</div>{group.keys.map(key=>{const m=modules.find(x=>x.key===key); const Icon=key==='dashboard'?LayoutDashboard:m!.Icon; return <button className={`nav-item ${active===key?'nav-item--active':''}`} key={key} onClick={()=>go(key)}><Icon size={18}/><span>{key==='dashboard'?t('dashboard'):isAr?m!.ar:m!.en}</span>{key==='leaves'&&pendingLeaves>0&&<i className="nav-badge">{pendingLeaves}</i>}</button>;})}</div>)}
      </nav>
      <div className="sidebar-bottom"><button className={`nav-item ${active==='settings'?'nav-item--active':''}`} onClick={()=>go('settings')}><Settings size={18}/><span>{t('settings')}</span></button><button className={`nav-item ${active==='about'?'nav-item--active':''}`} onClick={()=>go('about')}><Info size={18}/><span>{t('about')}</span></button><button className={`nav-item ${active==='support'?'nav-item--active':''}`} onClick={()=>go('support')}><LifeBuoy size={18}/><span>{t('support')}</span></button><div className="profile"><div className="profile-avatar">{(user?.fullName||'RA').split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase()}</div><div className="profile-copy"><b>{user?.fullName||(isAr?'ريم العتيبي':'Reem Alotaibi')}</b><small>{user?roleLabel(user.role,lang):(isAr?'مديرة النظام':'System admin')}</small></div><button className="icon-btn" title={t('signout')} onClick={onLogout}><LogOut size={17}/></button></div></div>
    </aside>
    {mobileNav&&<button className="scrim" onClick={()=>setMobileNav(false)} aria-label="Close navigation"/>}
    <main className="main-area">
      <header className="topbar"><div className="topbar-start"><button className="icon-btn mobile-menu" onClick={()=>setMobileNav(true)} aria-label="Menu"><Menu size={21}/></button><div className="breadcrumbs"><span>{t('brand')}</span><span className="crumb-sep">/</span><b>{current?(isAr?current.ar:current.en):active==='settings'?t('settings'):active==='about'?t('about'):active==='support'?t('support'):t('dashboard')}</b></div></div><div className="topbar-actions"><span className="today-label">{t('today')}</span><button className="language-btn" onClick={()=>setLang(isAr?'en':'ar')}><Globe2 size={17}/><span>{isAr?'English':'العربية'}</span></button><button className="icon-btn notification-btn" aria-label={t('notification')} onClick={()=>go('dashboard')}><Bell size={19}/>{(dueDocuments.length+expiredDocuments.length)>0&&<i/>}</button><div className="top-avatar">RA</div></div></header>
      <div className="page-content">
        {active==='dashboard'&&<>
          <div className="page-heading"><div><p className="eyebrow">{t('today')}</p><h1>{t('welcome')}{isAr?'، ':', '}{isAr?'ريم':'Reem'} <span>✦</span></h1><p>{t('subtitle')}</p></div><button className="primary-btn" onClick={()=>{setActive('employees');setSearch('');setStatusFilter('');setEditing(null);setForm({status:'نشط'});}}><Plus size={18}/>{t('add')}</button></div>
          <section className="kpi-grid">
            <Kpi title={t('totalEmployees')} value={number(employeeCount,lang)} icon={Users} color="navy" delta="+8.2%" lang={lang}/>
            <Kpi title={t('present')} value={number(presentCount,lang)} icon={Clock3} color="green" delta="+2.4%" lang={lang}/>
            <Kpi title={t('absentDays')} value={number(absenceDays,lang)} icon={Ban} color="red" delta="−3.1%" lang={lang}/>
            <Kpi title={t('totalLeaveDays')} value={number(totalLeaveDays,lang)} icon={CalendarDays} color="purple" delta={`${number(pendingLeaves,lang)} ${isAr?'قيد المراجعة':'pending'}`} lang={lang}/>
            <Kpi title={t('payroll')} value={`${number(payrollTotal,lang)} ${isAr?'ر.س':'SAR'}`} icon={Banknote} color="orange" delta="+4.6%" lang={lang}/>
            <Kpi title={t('advancesTotal')} value={`${number(advancesTotal,lang)} ${isAr?'ر.س':'SAR'}`} icon={Wallet} color="gray" delta={isAr?'هذا الشهر':'this month'} lang={lang}/>
            <Kpi title={t('expiredContracts')} value={number(expiredContracts,lang)} icon={FileText} color="brown" delta={isAr?'تحتاج مراجعة':'Review needed'} lang={lang}/>
            <Kpi title={t('averageSalary')} value={`${number(averageSalary,lang)} ${isAr?'ر.س':'SAR'}`} icon={ChartNoAxesCombined} color="blue" delta="+1.8%" lang={lang}/>
          </section>
          <section className="panel expiry-panel"><div className="panel-head"><div><h2><CalendarDays size={17}/> {t('expiryAlerts')}</h2><p>{isAr?'تذكيرات تلقائية حسب تاريخ الانتهاء':'Reminders based on document expiry dates'}</p></div><div className="expiry-thresholds">{[45,30,15,7].map(days=><span className={`threshold threshold-${days}`} key={days}>{remoteMode?(overview?.expiryBands?.[days]||0):dueDocuments.filter(doc=>expiryBand(doc.daysRemaining)===days).length} · {t(`alert${days}`)}</span>)}</div></div>
            {dueDocuments.length===0&&expiredDocuments.length===0?<div className="no-expiry">{t('noExpiringDocs')}</div>:<div className="expiry-list">{dueDocuments.slice(0,5).map(doc=>{const days=doc.daysRemaining;const group=doc.documentGroup;const row=doc.row;return <button className="expiry-item" key={row.id} onClick={()=>go(group)}><span className={`expiry-mark urgency-${expiryBand(days)}`}><CalendarDays size={17}/></span><span className="expiry-copy"><b>{row.name||row.documentType}</b><small>{group==='companyDocs'?t('companyDocs'):t('employeeDocs')} · {row.employeeName||row.authority||''}</small></span><span className={`expiry-days urgency-text-${expiryBand(days)}`}>{days===0?(isAr?'ينتهي اليوم':'Expires today'):`${number(days,lang)} ${t('daysLeft')}`}</span></button>;})}{expiredDocuments.slice(0,3).map(doc=><button className="expiry-item expired-item" key={`expired-${doc.row.id}`} onClick={()=>go(doc.documentGroup)}><span className="expiry-mark urgency-expired"><X size={17}/></span><span className="expiry-copy"><b>{doc.row.name||doc.row.documentType}</b><small>{t('expiredDocs')} · {doc.row.employeeName||doc.row.authority||''}</small></span><span className="expiry-days urgency-text-expired">{number(Math.abs(expiryDays(doc.row.expiresOn)||0),lang)} {isAr?'يوم منذ الانتهاء':'days overdue'}</span></button>)}</div>}
          </section>
          <section className="dashboard-lower"><div className="panel module-panel"><div className="panel-head"><div><h2>{t('quick')}</h2><p>{isAr?'انتقل مباشرة إلى إحدى وحدات النظام':'Jump into a workspace module'}</p></div><button className="text-btn" onClick={()=>go('employees')}>{t('allModules')} <ArrowUpRight size={15}/></button></div><div className="quick-grid">{modules.slice(0,8).map(m=><button key={m.key} className="quick-card" onClick={()=>go(m.key)}><span className={`quick-icon tone-${m.color}`}><m.Icon size={19}/></span><span>{isAr?m.ar:m.en}</span><ArrowDownRight size={15} className="quick-arrow"/></button>)}</div></div>
            <div className="panel activity-panel"><div className="panel-head"><div><h2>{t('recent')}</h2><p>{isAr?'نظرة سريعة على فريقك':'A snapshot of your team'}</p></div><button className="icon-btn" aria-label={t('viewAll')}><ChevronDown size={18}/></button></div><div className="activity-list"><ActivityItem icon={Users} color="navy" title={isAr?'تمت إضافة موظف جديد':'New employee added'} detail={isAr?'نورة أحمد · تقنية المعلومات':'Noura Ahmed · IT'} time={isAr?'منذ ساعتين':'2 hours ago'}/><ActivityItem icon={CalendarDays} color="purple" title={isAr?'طلب إجازة جديد':'New leave request'} detail={isAr?'نورة أحمد · ١٥–١٩ نوفمبر':'Noura Ahmed · Nov 15–19'} time={isAr?'منذ ٣ ساعات':'3 hours ago'}/><ActivityItem icon={Banknote} color="orange" title={isAr?'تمت مراجعة مسير الرواتب':'Payroll reviewed'} detail={isAr?'مسير نوفمبر · ٣ موظفين':'November payroll · 3 employees'} time={isAr?'أمس':'Yesterday'}/><ActivityItem icon={FileText} color="blue" title={isAr?'عقد يقترب من الانتهاء':'Contract nearing expiry'} detail={isAr?'عمر حسن · ١ ديسمبر':'Omar Hassan · Dec 1'} time={isAr?'أمس':'Yesterday'}/></div></div>
          </section>
          <div className="data-note"><ShieldCheck size={16}/><span>{isAr?'بيانات تجريبية محفوظة في هذا المتصفح. أضف سجلاتك أو عدّلها للبدء.':'Demo data is saved in this browser. Add or edit records to get started.'}</span></div>
        </>}
        {current&&<section className="module-view"><div className="page-heading module-heading"><div><p className="eyebrow">{isAr?'مساحة العمل':'Workspace'}</p><h1>{isAr?current.ar:current.en}</h1><p>{number(totalRows,lang)} {t('records')}</p></div><div className="heading-actions"><button className="secondary-btn" onClick={exportExcel}><Download size={17}/>{t('exportExcel')}</button><button className="secondary-btn" onClick={exportPdf}><FileText size={17}/>{t('exportPdf')}</button><button className="primary-btn" onClick={startCreate}><Plus size={18}/>{t('add')}</button></div></div>
          <div className="panel table-panel"><div className="table-toolbar"><label className="searchbox"><Search size={18}/><input value={search} onChange={e=>{setSearch(e.target.value);setCurrentPage(1);}} placeholder={t('search')}/><kbd>⌘ K</kbd></label><select className="filter-select" value={statusFilter} onChange={e=>{setStatusFilter(e.target.value);setCurrentPage(1);}}><option value="">{t('all')}</option>{['companyDocs','employeeDocs'].includes(current.key)?[['valid',isAr?'سارية':'Valid'],['expiring',isAr?'قاربت على الانتهاء':'Expiring soon'],['expired',isAr?'منتهية':'Expired']].map(([key,label])=><option key={key} value={key}>{label}</option>):Array.from(new Set([...rows,...(current.fields.find(f=>f.key==='status')?.options||[]).map(status=>({status}))].map(r=>typeof r.status==='string'?r.status:'').filter(Boolean))).map(s=><option key={s} value={s}>{translateStatus(s,lang)}</option>)}</select></div>
            {filtered.length===0?<div className="empty-state"><div className="empty-icon"><Search size={22}/></div><b>{rows.length===0?t('empty'):t('noResults')}</b></div>:<div className="table-scroll"><table><thead><tr>{tableFields.map(f=><th key={f.key}>{isAr?f.label:fieldEn(f.label)}</th>)}<th>{t('action')}</th></tr></thead><tbody>{current.key==='employeeDocs'?employeeGroups.flatMap(group=>{const first=group.rows[0];const open=!!expandedEmployees[group.key];const nearest=[...group.rows].filter(row=>expiryDays(row.expiresOn)!==null).sort((a,b)=>(expiryDays(a.expiresOn)||0)-(expiryDays(b.expiresOn)||0))[0];return [<tr className="employee-group-row" key={`group-${group.key}`}><td colSpan={tableFields.length+1}><button className="employee-group-toggle" onClick={()=>setExpandedEmployees(prev=>({...prev,[group.key]:!prev[group.key]}))}><ChevronDown className={open?'group-chevron group-chevron--open':'group-chevron'} size={17}/><span className="employee-group-name"><b>{first.employeeName}</b><small>{first.employeeNumber||''}</small></span><span className="employee-group-count">{number(group.rows.length,lang)} {t('documentsCount')}</span><span className="employee-group-nearest">{t('nearestExpiry')}: {nearest?.expiresOn||t('expiryUnknown')}</span></button></td></tr>,...(open?group.rows.map(renderDataRow):[])];}):filtered.map(renderDataRow)}</tbody></table></div>}
            <div className="table-foot"><span>{isAr?`عرض ${number(filtered.length,lang)} من ${number(totalRows,lang)} ${t('records')}`:`Showing ${filtered.length} of ${totalRows} ${t('records')}`}</span><span className="pagination-controls"><button className="secondary-btn" disabled={currentPage<=1} onClick={()=>setCurrentPage(page=>Math.max(1,page-1))}>{isAr?'السابق':'Previous'}</button><span>{isAr?`الصفحة ${number(currentPage,lang)} من ${number(pageCount,lang)}`:`Page ${currentPage} of ${pageCount}`}</span><button className="secondary-btn" disabled={currentPage>=pageCount} onClick={()=>setCurrentPage(page=>Math.min(pageCount,page+1))}>{isAr?'التالي':'Next'}</button></span></div>
          </div></section>}
        {active==='settings'&&<section className="module-view"><div className="page-heading"><div><p className="eyebrow">{isAr?'تفضيلاتك':'Preferences'}</p><h1>{t('settings')}</h1><p>{isAr?'إدارة إعدادات مساحة العمل':'Manage your workspace preferences'}</p></div></div><div className="panel settings-panel"><div className="setting-row"><span className="setting-icon"><Globe2 size={19}/></span><div><b>{isAr?'لغة الواجهة':'Interface language'}</b><small>{isAr?'اختر لغة عرض النظام':'Choose the display language'}</small></div><button className="language-btn" onClick={()=>setLang(isAr?'en':'ar')}>{isAr?'العربية':'English'} <ChevronDown size={15}/></button></div><div className="setting-row"><span className="setting-icon"><ShieldCheck size={19}/></span><div><b>{isAr?'الخصوصية والتخزين':'Privacy & storage'}</b><small>{remoteMode?(isAr?'قاعدة البيانات والوثائق محفوظة محلياً على الجهاز المضيف':'Database and files are stored on the local host'):(isAr?'البيانات محفوظة محلياً في هذا المتصفح':'Data is stored locally in this browser')}</small></div><button className="secondary-btn" onClick={()=>remoteMode?void createBackup():window.confirm(isAr?'مسح كل البيانات المحفوظة وإعادة البيانات التجريبية؟':'Clear saved data and restore demo data?')&&(localStorage.removeItem('rakeza-data'),setData(initialData),setToast(isAr?'تمت استعادة البيانات التجريبية':'Demo data restored'))}>{remoteMode?(isAr?'إنشاء نسخة احتياطية':'Create backup'):(isAr?'استعادة البيانات التجريبية':'Restore demo data')}</button></div>{remoteMode&&onChangeDeployment&&user?.role==='admin'&&<div className="setting-row"><span className="setting-icon"><Globe2 size={19}/></span><div><b>{t('changeDeviceMode')}</b><small>{t('changeDeviceModeHint')}</small></div><button className="secondary-btn" onClick={()=>window.confirm(isAr?'سيعاد تشغيل البرنامج لاختيار نمط الجهاز. متابعة؟':'The app will restart to change device mode. Continue?')&&onChangeDeployment()}>{t('changeDeviceMode')}</button></div>}</div></section>}
        {active==='settings'&&remoteMode&&user?.role==='admin'&&<section className="panel user-admin-panel"><div className="panel-head"><div><h2>{t('userAccounts')}</h2><p>{isAr?'إدارة الوصول إلى مساحة المؤسسة':'Manage access to the organization workspace'}</p></div></div><form className="user-create-form" onSubmit={createTeamUser}><label className="form-field"><span>{t('userFullName')}</span><input name="fullName" required/></label><label className="form-field"><span>{isAr?'البريد الإلكتروني':'Email'}</span><input name="email" type="email" required/></label><label className="form-field"><span>{t('userRole')}</span><select name="role" defaultValue="hr"><option value="hr">{roleLabel('hr',lang)}</option><option value="manager">{roleLabel('manager',lang)}</option><option value="viewer">{roleLabel('viewer',lang)}</option><option value="admin">{roleLabel('admin',lang)}</option></select></label><label className="form-field"><span>{t('passwordMin')}</span><input name="password" type="password" minLength={12} required/></label><button className="primary-btn"><Plus size={16}/>{t('addUser')}</button></form><div className="team-user-list">{teamUsers.map(item=><div className="team-user-row" key={item.id}><span className="profile-avatar">{item.fullName.split(' ').slice(0,2).map(x=>x[0]).join('')}</span><span className="team-user-copy"><b>{item.fullName}</b><small>{item.email}</small></span><span className="team-user-role">{roleLabel(item.role,lang)}</span><span className={`team-user-state ${item.isActive?'team-user-state--active':''}`}>{item.isActive?t('active'):t('inactive')}</span><button className="secondary-btn" disabled={item.id===user.id} onClick={()=>void toggleTeamUser(item)}>{item.isActive?t('deactivate'):t('activate')}</button></div>)}</div></section>}
        {active==='about'&&<section className="module-view info-page"><div className="page-heading"><div><p className="eyebrow">{isAr?'منصة ركيزة':'Rakeza platform'}</p><h1>{t('about')}</h1><p>{t('aboutTagline')}</p></div></div><article className="panel about-hero"><div className="about-mark"><img src="/rakeza-mark.jpg" alt="Rakeza HR"/></div><div><span className="about-brand">{t('brand')}</span><h2>{t('aboutTagline')}</h2><p>{t('aboutDescription')}</p></div></article><div className="about-feature-grid"><article className="panel about-feature"><span className="quick-icon tone-navy"><Users size={20}/></span><b>{t('aboutPeople')}</b></article><article className="panel about-feature"><span className="quick-icon tone-teal"><ShieldCheck size={20}/></span><b>{t('aboutDocs')}</b></article><article className="panel about-feature"><span className="quick-icon tone-purple"><ChartNoAxesCombined size={20}/></span><b>{t('aboutInsights')}</b></article></div></section>}
        {active==='support'&&<section className="module-view info-page"><div className="page-heading"><div><p className="eyebrow">{isAr?'مركز المساعدة':'Help center'}</p><h1>{t('support')}</h1><p>{t('supportIntro')}</p></div></div><div className="support-grid"><a className="panel support-card" href="mailto:thsedahmed@gmail.com?subject=Rakeza%20HR%20Support"><span className="support-icon"><Mail size={21}/></span><span className="support-copy"><small>{isAr?'البريد الإلكتروني':'Email support'}</small><b>thsedahmed@gmail.com</b></span><span className="support-action">{t('emailUs')} ↗</span></a><a className="panel support-card" href="mailto:thsedahmed@hotmail.com?subject=Rakeza%20HR%20Support"><span className="support-icon"><Mail size={21}/></span><span className="support-copy"><small>{isAr?'البريد الإلكتروني':'Email support'}</small><b>thsedahmed@hotmail.com</b></span><span className="support-action">{t('emailUs')} ↗</span></a></div></section>}
      </div>
    </main>
    {form&&((current&& (editing!==null || Object.keys(form).length>0)))&&<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget){setForm({});setEditing(null);setPendingAttachment(null);}}}><section className="record-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div className="modal-head"><div><span className={`modal-icon tone-${current?.color}`}>{current&&<current.Icon size={20}/>}</span><div><h2 id="modal-title">{editing?(isAr?'تعديل السجل':'Edit record'):t('add')}</h2><p>{current?(isAr?current.ar:current.en):''}</p></div></div><button className="icon-btn" onClick={()=>{setForm({});setEditing(null);setPendingAttachment(null);}} aria-label="Close"><X size={19}/></button></div><div className="modal-fields">{current?.fields.filter(field=>field.type!=='computed').map(field=><label className="form-field" key={field.key}><span>{isAr?field.label:fieldEn(field.label)}{(['name','number','employeeName','documentNo','expiresOn'].includes(field.key))&&<i> *</i>}</span>{field.options?<select value={form[field.key]||''} onChange={e=>setForm(v=>({...v,[field.key]:e.target.value}))}><option value="">{isAr?'اختر':'Select'}</option>{field.options.map(option=><option key={option} value={option}>{translateStatus(option,lang)}</option>)}</select>:field.type==='file'?<><input type="file" accept=".pdf,.png,.jpg,.jpeg,.webp" onChange={e=>{const file=e.target.files?.[0]||null;setPendingAttachment(file);if(file)setForm(v=>({...v,attachmentName:file.name}));}}/><small className="file-hint">{pendingAttachment?.name||form.attachmentName||(isAr?'PDF أو صورة':'PDF or image')}</small></>:<input type={field.type||'text'} value={form[field.key]||''} onChange={e=>setForm(v=>({...v,[field.key]:e.target.value}))} placeholder={isAr?`أدخل ${field.label}`:`Enter ${fieldEn(field.label).toLowerCase()}`}/>}</label>)}</div><div className="modal-actions"><button className="secondary-btn" onClick={()=>{setForm({});setEditing(null);setPendingAttachment(null);}}>{t('cancel')}</button><button className="primary-btn" onClick={saveRecord}><Check size={17}/>{t('save')}</button></div></section></div>}
    {toast&&<div className="toast"><Check size={17}/>{toast}</div>}
  </div>;
}

function roleLabel(role:string,lang:Lang){return lang==='ar'?({admin:'مسؤول النظام',hr:'الموارد البشرية',manager:'مدير',viewer:'مشاهد'} as Record<string,string>)[role]||role:({admin:'Administrator',hr:'HR',manager:'Manager',viewer:'Viewer'} as Record<string,string>)[role]||role;}
function Kpi({title,value,icon:Icon,color,delta,lang}:{title:string;value:string;icon:typeof Users;color:string;delta:string;lang:Lang}){return <article className="kpi-card"><div className="kpi-top"><span>{title}</span><span className={`kpi-icon tone-${color}`}><Icon size={19}/></span></div><div className="kpi-bottom"><strong>{value}</strong><span className="kpi-delta">{delta.startsWith('+')&&<ArrowUpRight size={14}/>} {delta}</span></div><small>{lang==='ar'?'مقارنة بالشهر الماضي':'vs last month'}</small></article>}
function ActivityItem({icon:Icon,color,title,detail,time}:{icon:typeof Users;color:string;title:string;detail:string;time:string}){return <div className="activity-item"><span className={`activity-icon tone-${color}`}><Icon size={17}/></span><div className="activity-copy"><b>{title}</b><span>{detail}</span></div><time>{time}</time></div>}
function statusTone(status:string){return status==='معتمد'||status==='نشط'||status==='حاضر'||status==='جاهز'||status==='مسدد'?'success':status==='مرفوض'||status==='غائب'||status==='منتهي'?'danger':status==='متأخر'?'warning':'pending';}
function ExpiryBadge({date,lang,t}:{date:string|undefined;lang:Lang;t:(key:string)=>string}){const days=expiryDays(date);if(days===null)return <span className="status-pill pending"><i/>{t('expiryUnknown')}</span>;if(days<0)return <span className="status-pill danger"><i/>{t('expired')}</span>;if(days<=45)return <span className={`status-pill ${days<=7?'danger':days<=15?'warning':'pending'}`}><i/>{lang==='ar'?`متبقي ${number(days,lang)} يوم`:`${number(days,lang)} days left`}</span>;return <span className="status-pill success"><i/>{t('valid')}</span>;}
function expiryDescription(date:string|undefined,lang:Lang){const d=expiryDays(date);if(d===null)return lang==='ar'?'غير محدد':'Not set';if(d<0)return lang==='ar'?'منتهية':'Expired';return lang==='ar'?`متبقي ${number(d,lang)} يوم`:`${number(d,lang)} days left`;}
function fieldEn(field:string){return ({'الاسم الكامل':'Full name','الرقم الوظيفي':'Employee ID','القسم':'Department','المسمى الوظيفي':'Job title','رقم الجوال':'Phone number','الحالة':'Status','حالة الصلاحية':'Expiry status','اسم الموظف':'Employee name','التاريخ':'Date','وقت الحضور':'Check-in','وقت الانصراف':'Check-out','عدد الأيام':'Days','الأيام':'Days','السبب':'Reason','نوع الإجازة':'Leave type','من تاريخ':'From','إلى تاريخ':'To','الراتب (ر.س)':'Salary (SAR)','الفترة':'Period','الخصومات':'Deductions','المبلغ (ر.س)':'Amount (SAR)','تاريخ الطلب':'Request date','عدد الأقساط':'Installments','نوع العقد':'Contract type','تاريخ البداية':'Start date','تاريخ الانتهاء':'Expiry date','اسم الملف':'File name','المرفق':'Attachment','التصنيف':'Category','الموظف/المالك':'Employee / owner','تاريخ الإضافة':'Added date','اسم التقرير':'Report name','أُعد بواسطة':'Prepared by','تاريخ الإنشاء':'Created date','اسم الوثيقة':'Document name','نوع الوثيقة':'Document type','رقم الوثيقة':'Document number','الجهة المصدرة':'Issuing authority','تاريخ الإصدار':'Issue date'} as Record<string,string>)[field]||field;}
function openDocumentDb():Promise<IDBDatabase>{return new Promise((resolve,reject)=>{const request=indexedDB.open('rakeza-document-files',1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('files'))request.result.createObjectStore('files');};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
async function storeDocumentFile(id:string,file:File){const db=await openDocumentDb();await new Promise<void>((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(file,id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);});db.close();}
async function readDocumentFile(id:string):Promise<Blob|undefined>{const db=await openDocumentDb();const result=await new Promise<Blob|undefined>((resolve,reject)=>{const request=db.transaction('files','readonly').objectStore('files').get(id);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});db.close();return result;}
async function removeDocumentFile(id:string){const db=await openDocumentDb();await new Promise<void>((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').delete(id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);});db.close();}
